function buildSecuritySupplement(){
  const result=[];
  for(const [domain,sets] of Object.entries(SECURITY_SUPPLEMENT_SEEDS)){
    sets.single.forEach(([group,stems,options,correct,explanation],i)=>stems.forEach((stem,variant)=>{const item=q(`sx-${domain}-s${String(i+1).padStart(2,'0')}-${variant+1}`,domain,stem,options,correct,explanation);item.topicGroup=`sx-${domain}-${group}`;result.push(item);}));
    sets.multi.forEach(([group,stems,options,correct,explanation],i)=>stems.forEach((stem,variant)=>{const item=q(`sx-${domain}-m${String(i+1).padStart(2,'0')}-${variant+1}`,domain,stem,options,correct,explanation,true);item.topicGroup=`sx-${domain}-${group}`;result.push(item);}));
    sets.pbq.forEach(([group,prompt,labels,fieldOptions,correct,explanation],i)=>{
      const stems=[prompt,`PBQ: In a security review, ${prompt[0].toLowerCase()+prompt.slice(1)}`,`PBQ: Apply the scenario to this practical task: ${prompt}`,`PBQ: Complete the operational matching exercise. ${prompt}`,`PBQ: During a control-design workshop, ${prompt[0].toLowerCase()+prompt.slice(1)}`];
      const fields=labels.map((label,n)=>({label,options:fieldOptions[n],correct:correct[n]}));
      stems.forEach((stem,variant)=>{const item=pbq(`sx-${domain}-p${String(i+1).padStart(2,'0')}-${variant+1}`,domain,stem,fields,explanation);item.topicGroup=`sx-${domain}-${group}`;result.push(item);});
    });
  }
  return result;
}
const SECURITY_SUPPLEMENT_BANK=buildSecuritySupplement();
const SECURITY_ACTIVE_BANK=[...SECURITY_BOOK_BANK,...SECURITY_SUPPLEMENT_BANK];
if (SECURITY_BOOK_BANK.length !== 250) console.warn(`Expected 250 book-aligned Security+ questions, found ${SECURITY_BOOK_BANK.length}`);
if (SECURITY_SUPPLEMENT_BANK.length !== 500) console.warn(`Expected 500 supplemental Security+ questions, found ${SECURITY_SUPPLEMENT_BANK.length}`);


